class Solution:
    def countOfPeaks(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        peaks = [0] * n

        # Helper to check if an index is a peak
        def is_peak(i):
            if i <= 0 or i >= n - 1:
                return False
            return nums[i - 1] < nums[i] > nums[i + 1]

        # Initialize peaks array
        for i in range(1, n - 1):
            if is_peak(i):
                peaks[i] = 1

        # Fenwick Tree (Binary Indexed Tree) for prefix sums of peaks
        class Fenwick:
            def __init__(self, n):
                self.n = n
                self.bit = [0] * (n + 1)

            def update(self, idx, delta):
                idx += 1
                while idx <= self.n:
                    self.bit[idx] += delta
                    idx += idx & -idx

            def query(self, idx):
                # sum from 0 to idx inclusive
                idx += 1
                res = 0
                while idx > 0:
                    res += self.bit[idx]
                    idx -= idx & -idx
                return res

            def range_sum(self, l, r):
                if l > r:
                    return 0
                return self.query(r) - self.query(l - 1)

        bit = Fenwick(n)
        for i in range(n):
            if peaks[i]:
                bit.update(i, 1)

        res = []

        for q in queries:
            if q[0] == 1:
                l, r = q[1], q[2]
                # First and last element of subarray cannot be peaks, so we query (l+1, r-1)
                if l + 1 <= r - 1:
                    res.append(bit.range_sum(l + 1, r - 1))
                else:
                    res.append(0)
            else:  # type 2
                idx, val = q[1], q[2]
                if nums[idx] == val:
                    continue

                old_val = nums[idx]
                nums[idx] = val

                # Check peaks at idx-1, idx, idx+1
                for i in range(idx - 1, idx + 2):
                    if i <= 0 or i >= n - 1:
                        continue
                    old_peak = is_peak(i) if nums[i] == old_val else peaks[i]
                    new_peak = is_peak(i)
                    if old_peak != new_peak:
                        delta = 1 if new_peak else -1
                        peaks[i] = 1 if new_peak else 0
                        bit.update(i, delta)

        return res
