class Solution:
    def countOfPeaks(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        class Fenwick:
            def __init__(self, n):
                self.n = n
                self.bit = [0] * (n + 1)
            def update(self, i, delta):
                while i <= self.n:
                    self.bit[i] += delta
                    i += i & -i
            def sum(self, i):
                res = 0
                while i > 0:
                    res += self.bit[i]
                    i -= i & -i
                return res

        n = len(nums)
        fw = Fenwick(n)
        is_peak = [0] * n

        def check_peak(i):
            return 1 if 0 < i < n-1 and nums[i] > nums[i-1] and nums[i] > nums[i+1] else 0

        # initialize peaks
        for i in range(1, n-1):
            is_peak[i] = check_peak(i)
            if is_peak[i]:
                fw.update(i+1, 1)

        res = []
        for q in queries:
            if q[0] == 1:
                l, r = q[1], q[2]
                if r - l < 2:
                    res.append(0)
                else:
                    L = l + 1
                    R = r - 1
                    # fenwick indices are original index + 1
                    ans = fw.sum(R + 1) - fw.sum(L)
                    res.append(ans)
            else:
                idx, val = q[1], q[2]
                if nums[idx] == val:
                    continue
                nums[idx] = val
                for j in (idx-1, idx, idx+1):
                    if 0 < j < n-1:
                        new = check_peak(j)
                        if new != is_peak[j]:
                            fw.update(j+1, new - is_peak[j])
                            is_peak[j] = new
        return res
