class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        count = {}

        # Count occurrences in each subarray of size k
        for start in range(n - k + 1):
            subarray = nums[start:start + k]
            seen_in_subarray = set()
            for num in subarray:
                if num not in seen_in_subarray:
                    count[num] = count.get(num, 0) + 1
                    seen_in_subarray.add(num)

        # Find the largest integer with count == 1
        result = -1
        for num, freq in count.items():
            if freq == 1 and num > result:
                result = num

        return result
