import math

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        def lcm(a: int, b: int) -> int:
            return a // math.gcd(a, b) * b

        best = 0
        # consider no removal (skip = -1) and removal of each index
        for skip in range(-1, n):
            g = 0
            L = 1
            count = 0
            for i in range(n):
                if i == skip:
                    continue
                x = nums[i]
                if g == 0:
                    g = x
                else:
                    g = math.gcd(g, x)
                L = lcm(L, x)
                count += 1
            if count == 0:
                score = 0
            else:
                score = g * L
            if score > best:
                best = score
        return best
