class Solution:
    def minimumSubstringsInPartition(self, s: str) -> int:
        n = len(s)
        # prefix counts: pref[i][c] = count of char c in s[:i]
        pref = [[0]*26 for _ in range(n+1)]
        for i, ch in enumerate(s):
            c = ord(ch) - 97
            for k in range(26):
                pref[i+1][k] = pref[i][k]
            pref[i+1][c] += 1

        INF = n + 1
        dp = [INF] * (n+1)
        dp[0] = 0

        for i in range(1, n+1):
            # try all possible previous cut positions j (substring s[j:i])
            for j in range(i-1, -1, -1):
                # compute counts for s[j:i]
                cnt = None
                balanced = True
                for k in range(26):
                    ccount = pref[i][k] - pref[j][k]
                    if ccount > 0:
                        if cnt is None:
                            cnt = ccount
                        elif ccount != cnt:
                            balanced = False
                            break
                if balanced:
                    # cnt must not be None because substring length > 0
                    dp[i] = min(dp[i], dp[j] + 1)
        return dp[n]
