                # We need two points that can be opposite corners of a rectangle
                # For axis-aligned rectangle, they must have x1 != x2 and y1 != y2
                if x1 != x2 and y1 != y2:
                    # Check if the other two corners exist
                    if (x1, y2) in point_set and (x2, y1) in point_set:
