from typing import List

class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        def area_below(h: float) -> float:
            """Calculate total area below horizontal line y = h"""
            total = 0.0
            for _, y, l in squares:
                if h <= y:
                    continue  # No area below
                elif h >= y + l:
                    total += l * l  # Entire square is below
                else:
                    total += l * (h - y)  # Partial square below
            return total

        # Find the range of possible y-values for the line
        min_y = min(y for _, y, _ in squares)
        max_y = max(y + l for _, y, l in squares)

        # Total area of all squares
        total_area = sum(l * l for _, _, l in squares)
        target = total_area / 2.0

        # Binary search for the correct y-coordinate
        left, right = min_y, max_y
        for _ in range(100):  # Enough iterations for required precision
            mid = (left + right) / 2.0
            below = area_below(mid)

            if below < target:
                left = mid
            else:
                right = mid

        return (left + right) / 2.0

