class Solution:
    def minAnagramLength(self, s: str) -> int:
        n = len(s)

        # Try all possible lengths from smallest to largest
        for k in range(1, n + 1):
            if n % k != 0:
                continue

            # Frequency of first segment
            first_freq = [0] * 26
            for i in range(k):
                first_freq[ord(s[i]) - ord('a')] += 1

            valid = True
            # Check each subsequent segment
            for seg in range(1, n // k):
                freq = [0] * 26
                start = seg * k
                for i in range(start, start + k):
                    freq[ord(s[i]) - ord('a')] += 1
                if freq != first_freq:
                    valid = False
                    break

            if valid:
                return k

        return n  # fallback, should never reach here for valid input

