    H = int(data[idx]); idx += 1
    W = int(data[idx]); idx += 1
    K = int(data[idx]); idx += 1

    grid = []
    for _ in range(H):
        grid.append(data[idx]); idx += 1

    # Prefix sums for 'o' and 'x'
    pref_o = [[0]*(W+1) for _ in range(H+1)]
    pref_x = [[0]*(W+1) for _ in range(H+1)]

    for i in range(H):
        for j in range(W):
            pref_o[i+1][j+1] = pref_o[i+1][j] + pref_o[i][j+1] - pref_o[i][j]
            pref_x[i+1][j+1] = pref_x[i+1][j] + pref_x[i][j+1] - pref_x[i][j]
            if grid[i][j] == 'o':
                pref_o[i+1][j+1] += 1
            elif grid[i][j] == 'x':
                pref_x[i+1][j+1] += 1

    def rect_sum(pref, r1, c1, r2, c2):
        # r1, c1 inclusive top-left, r2, c2 exclusive bottom-right
        return pref[r2][c2] - pref[r1][c2] - pref[r2][c1] + pref[r1][c1]

    INF = 10**9
    ans = INF

    # Horizontal windows
    for i in range(H):
        for j in range(W - K + 1):
            cnt_x = rect_sum(pref_x, i, j, i+1, j+K)
            if cnt_x > 0:
                continue
            cnt_o = rect_sum(pref_o, i, j, i+1, j+K)
            ans = min(ans, K - cnt_o)

    # Vertical windows
    for j in range(W):
        for i in range(H - K + 1):
            cnt_x = rect_sum(pref_x, i, j, i+K, j+1)
            if cnt_x > 0:
                continue
            cnt_o = rect_sum(pref_o, i, j, i+K, j+1)
            ans = min(ans, K - cnt_o)

    if ans == INF:
        print(-1)
    else:
        print(ans)

